// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // owner of c is address(0) (no constructor set), so owner approves the actor
        vm.prank(address(0));
        c.setApprovedLogger(actor, true);
        vm.prank(actor);
        bool ok = c.logCreated(address(1));
        assertTrue(ok);
    }
}
